INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-desafio-vocal', 'El Desafío Vocal', 'Dinámica de afinación lírica y expresión afectiva donde los scouts ejercitan melodías e interpretación en canciones de campamento.', '<h2>📜 Descripción de El Desafío Vocal</h2>
<p><b>El Desafío Vocal</b> es una dinámica de expresión melódica, modulación de voz y pertenencia institucional. Ubicados en círculo en el salón o junto a la fogata, los scouts ejercitan vocalizaciones rítmicas guiadas por el director del juego. Al sonido de una nota o pauta (ej. <i>''Cantar la primera estrofa usando únicamente la vocal A''</i> o <i>''Modular in crescendo del susurro al gran rugido''</i>), los participantes entonan estrofas de canciones scouts tradicionales adaptando el volumen, tono y vocalización colectiva en tiempo real.</p>
<p>Esta actividad fortalece la sensibilidad artística, el oído musical y el sentido de pertenencia en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega El Desafío Vocal?</h2>
<p>Para llevar a cabo la dinámica con solemnidad y alegría, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Formación en Círculo:</b> La unidad se sienta en círculo sobre el césped o bancas de fogata.</li>
  <li><b>Calentamiento de Voz:</b> El animador guía ejercicios suaves de respiración diafragmática y resonancia.</li>
  <li><b>Consigna de Vocalización:</b> Se asigna una modificación a la canción (ej. <i>''Sustituir todas las vocales por la letra O''</i> o <i>''Cantar en canon de tres partes''</i>).</li>
  <li><b>Interpretación Melódica:</b> Las seisenas, patrullas o comunidades entonan la canción scout manteniendo el ritmo sin perder la afinación.</li>
  <li><b>Aplauso de Fogata:</b> Al concluir la ronda, la unidad entona el tradicional grito o aplauso Scout.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Desafío Vocal</h2>
<p>La actividad valora la expresión afectiva y la armonía en el Tally:</p>
<ul>
  <li><b>Mayor Armonía Vocal:</b> Otorgar 5 puntos al equipo que mantenga la modulación melódica sin desafinaciones.</li>
  <li><b>Creatividad en la Variación:</b> Otorgar 3 puntos al grupo que interprete las consignas vocales con mayor humor y soltura.</li>
  <li><b>Entusiasmo Colectivo:</b> Otorgar 3 puntos a la unidad que demuestre mayor pasión al entonar la canción.</li>
</ul>', '/uploads/el-desafio-vocal.webp', 'publicado', '{"areas": ["creatividad", "afectividad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Sin Materiales"], "objetivos": ["Estimular la creatividad", "Estimular la capacidad de reacción", "Fomentar la comunicación en el grupo", "Crear un clima de pertenencia"], "justificacion_areas": "El Desafío Vocal potencia la creatividad al estimular el oído melódico, la modulación vocal y la improvisación de variaciones líricas. Desarrolla la afectividad al construir un clima de calidez, pertenencia e integración desde Manada hasta Clan.", "variaciones": "<b>Canon Tridimensional:</b> Dividir la unidad en tres grupos que entonan estrofas cruzadas en tiempos desfasados.<br><b>Vocalización con Percusión Corporal:</b> Acompañar el ritmo vocal con chasquidos, pisadas y palmas en el pecho.<br><b>Himno del Grupo Scout Nua Mana:</b> Ensayar y perfeccionar las estrofas del himno institucional.", "recomendaciones": "Asegurar que los ejercicios vocales sean progresivos para cuidar la voz de los participantes. Mantener una atmósfera cálida e inclusiva.", "objetivos_educativos": [{"id": "52b5580a-7d0f-454f-b2ae-0d3318129165", "area": "Creatividad", "unidad": "Manada", "texto": "Canto, bailo y preparo actuaciones con mis amigos de la Manada.", "como_se_cumple": "Entonando canciones scouts con alegría y modulación vocal colectiva."}, {"id": "14b82459-ac31-4496-a875-8e9bd5666030", "area": "Creatividad", "unidad": "Manada", "texto": "En las actividades que hago se nota lo que pienso y siento.", "como_se_cumple": "Expresando sentimientos de pertenencia a través de la interpretación lírica."}, {"id": "ab6e594f-b0a0-4e6d-96aa-7779299b02ef", "area": "Afectividad", "unidad": "Manada", "texto": "Trato con cariño a los demás en la Manada y me gusta que me traten igual.", "como_se_cumple": "Compartiendo un ambiente de calidez y fraternidad al cantar unidos."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "area": "Afectividad", "unidad": "Manada", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "como_se_cumple": "Respetando los distintos tonos y voces de los lobatos al cantar."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "unidad": "Compañía", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "como_se_cumple": "Liderando vocalizaciones y cánones melódicos en la unidad."}, {"id": "0136350b-c2b2-429f-8feb-2fdc57e29b8b", "area": "Creatividad", "unidad": "Compañía", "texto": "Me gusta cantar y conozco muchas canciones.", "como_se_cumple": "Enseñando y modulando el repertorio de canciones de campamento."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "unidad": "Compañía", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Sintonizando la voz con el tono del grupo para lograr armonía."}, {"id": "672a5da0-8cab-42bb-85dd-0d1f285a1b91", "area": "Afectividad", "unidad": "Compañía", "texto": "Digo lo que pienso con respeto hacia las demás personas.", "como_se_cumple": "Creando un clima afectivo de confianza e integración artística."}, {"id": "39eaf1aa-f703-4fd0-a4b3-b9756dc30539", "area": "Creatividad", "unidad": "Tropa", "texto": "Participo con entusiasmo en las actividades artísticas de mi Tropa.", "como_se_cumple": "Fortaleciendo la tradición lírica y musical en la Tropa."}, {"id": "6e910d1c-7021-49a5-9ece-637f480a1ec7", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Demostrando dominio del tono, volumen y ritmo en cantos de fogata."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "unidad": "Tropa", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Fomentando el respeto y la escucha atenta de las voces de los pares."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "unidad": "Tropa", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "como_se_cumple": "Afianzando la mística y la fraternidad de la patrulla mediante el canto."}, {"id": "ed17d59c-1c64-4080-a206-bbe72eeae5a4", "area": "Creatividad", "unidad": "Avanzada", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Liderando la interpretación melódica y la vivencia lírica en la Avanzada."}, {"id": "3b32ea2c-da58-487c-bea4-e02f301f5e3e", "area": "Afectividad", "unidad": "Avanzada", "texto": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "como_se_cumple": "Construyendo espacios de encuentro afectivo y canto compartido sin inhibiciones."}, {"id": "91e60eba-e267-4d1a-b27b-ef61a7b03b31", "area": "Creatividad", "unidad": "Clan", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Fomentando el canto institucional y el perfeccionamiento artístico en el Clan."}, {"id": "d0ba748f-313b-4ffe-b2a3-fb21c1f8943f", "area": "Afectividad", "unidad": "Clan", "texto": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "como_se_cumple": "Promoviendo la hermandad alegre y el canto fraterno en el Clan Rover."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

